from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base ATAX kernel:
#   tmp[i] = sum_j A[i,j] * x[j]
#   y[j]  += sum_i A[i,j] * tmp[i]
#
# We keep the mathematical algorithm, but:
#   - Use a scalar accumulator 'acc' instead of repeatedly loading tmp[i].
#   - Apply loop tiling in the i-dimension (rows of A) to improve cache
#     behavior on large matrices.
#   - Parallelize the y-initialization loop, which is embarrassingly parallel.

@proc
def kernel_atax_unoptimized(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Initialize y to zero.
    for j in seq(0, n):
        y[j] = 0.0

    # Main computation:
    #   For each row i:
    #     acc = dot(A[i, :], x)
    #     tmp[i] = acc
    #     y[:]  += acc * A[i, :]
    for i in seq(0, m):
        acc: DATA_TYPE
        acc = 0.0
        for j in seq(0, n):
            acc += A[i, j] * x[j]
        tmp[i] = acc
        for j in seq(0, n):
            y[j] += A[i, j] * acc


