# Scheduling / Optimization
# --------------------
kernel_atax_scheduled = kernel_atax_unoptimized

# 1) Parallelize the y-initialization loop over j.
#    Each iteration writes a distinct y[j], so this is a safe parallel loop.
j_init = kernel_atax_scheduled.find_loop("j #0")
kernel_atax_scheduled = parallelize_loop(kernel_atax_scheduled, j_init)

# 2) Tile the main loop over i (rows of A) to improve spatial locality.
#    TILE_I is a tunable constant controlling the tile size along m.
TILE_I = 32  # row tile size; can be tuned for the target cache hierarchy

i_main = kernel_atax_scheduled.find_loop("i")
kernel_atax_scheduled = divide_loop(
    kernel_atax_scheduled,
    i_main,
    TILE_I,
    ("io", "ii"),
    tail="guard",
)

