/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *
from exo.stdlib.stdlib import tile_loops

# Baseline ATAX kernel: y = A^T * (A * x)
@proc
def kernel_atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Basic sanity checks on problem size.
    assert m >= 1
    assert n >= 1

    # Initialize y to zero.
    for j in seq(0, n):
        y[j] = 0.0

    # First stage: tmp = A * x  (matrix–vector product).
    # Each iteration of this loop is independent of the others.
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # Second stage: y = y + A^T * tmp.
    # We traverse A row-wise again to preserve good spatial locality.
    for i in seq(0, m):
        # Hoist tmp[i] into a scalar so that the C compiler can
        # keep it in a register instead of reloading from memory.
        ti: DATA_TYPE
        ti = tmp[i]
        for j in seq(0, n):
            y[j] += A[i, j] * ti

# ---------------------------------------------------------------------------
# Scheduling: improve locality and parallelism while preserving semantics.
# ---------------------------------------------------------------------------

# Tile size for the j dimension. This constant is a tuning knob: it should be
# large enough to expose ILP and allow vectorization, but small enough to keep
# the working set in cache and avoid excessive code size from unrolling.
TILE_J = 32

p = kernel_atax_base

# 1) Parallelize the y-initialization loop over j. Each iteration writes a
#    distinct element of y, so there are no loop-carried dependencies.
init_j = p.find_loop("j")
p = parallelize_loop(p, init_j)

# 2) Parallelize the tmp-computation loop over i. Each tmp[i] is written once
#    and depends only on row i of A and the read-only vector x.
i_tmp = p.find_loop("i #0")
p = parallelize_loop(p, i_tmp)

# 3) Tile and unroll the inner j loop in the tmp computation.
#    This improves locality over A's rows and x, and exposes ILP that helps
#    the backend auto-vectorize.
j_tmp = p.find_loop("j #1")  # second j-loop: inner loop of the tmp computation
p = divide_loop(p, j_tmp, TILE_J, ("j_tmp_outer", "j_tmp_inner"), tail="guard")

# The inner tile has a fixed bound (TILE_J), so it is safe to fully unroll.
j_tmp_inner = p.find_loop("j_tmp_inner")
p = unroll_loop(p, j_tmp_inner)

# 4) Tile and unroll the inner j loop in the y update.
#    This keeps accesses to y and each row of A contiguous within a tile and
#    again exposes ILP for the C compiler.
j_y = p.find_loop("j #1")  # after tiling tmp, the second j-loop is in the y update
p = divide_loop(p, j_y, TILE_J, ("j_y_outer", "j_y_inner"), tail="guard")

j_y_inner = p.find_loop("j_y_inner")
p = unroll_loop(p, j_y_inner)

# 5) Simplify the resulting code: constant-fold guards, remove dead branches,
#    and clean up any algebraic redundancies introduced by the transforms.
p = simplify(p)

# 6) Export the optimized kernel under the original name expected by the
#    C driver and PolyBench harness.
kernel_atax = rename(p, "kernel_atax")
EXO END
