/*
 * Kernel implementation in Exo.
 *
 * This Exo code is extracted by the Exo toolchain, scheduled, and
 * compiled into the C kernel declared in generated/atax/atax.h.
 *
 * We implement ATAX as:
 *   tmp[i] = sum_j A[i,j] * x[j]
 *   y[j]   = sum_i A[i,j] * tmp[i]
 *
 * Optimizations:
 *  - Use scalar accumulators (tmp_i_acc, y_j_acc) to keep reductions
 *    in registers and minimize memory traffic to tmp[]/y[].
 *  - Restructure into two clear stages: A*x then A^T*tmp.
 *  - Parallelize the outer loop over j in the second stage. Each
 *    iteration updates a distinct y[j] and only reads shared A/tmp,
 *    so there are no cross-iteration write conflicts. This is lowered
 *    to an OpenMP parallel loop by Exo’s backend.
 *
 * All buffers use the placeholder DATA_TYPE so the same kernel can be
 * instantiated for different precisions at code-generation time.
 */
/* EXO START */
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Base ATAX kernel: compute y = A^T (A x)
@proc
def kernel_atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Stage 1: tmp[i] = sum_j A[i,j] * x[j]
    #
    # tmp_i_acc is a scalar accumulator kept in a register; we write
    # tmp[i] only once per row after the inner loop finishes.
    tmp_i_acc: DATA_TYPE
    for i in seq(0, m):
        tmp_i_acc = 0.0
        for j in seq(0, n):
            tmp_i_acc += A[i, j] * x[j]
        tmp[i] = tmp_i_acc

    # Stage 2: y[j] = sum_i A[i,j] * tmp[i]
    #
    # y_j_acc is a scalar accumulator for a single output element y[j].
    # We compute the full dot product for column j into y_j_acc, then
    # store it once into y[j]. Each j-iteration is independent.
    y_j_acc: DATA_TYPE
    for j in seq(0, n):
        y_j_acc = 0.0
        for i2 in seq(0, m):
            y_j_acc += A[i2, j] * tmp[i2]
        y[j] = y_j_acc


# ------------------------
# Scheduling / optimization
# ------------------------

# Start from the base kernel.
p = kernel_atax_base

# Parallelize the outer loop over j in Stage 2.
# This is safe because each iteration operates on a distinct y[j] and
# uses only read-only data (A and tmp), so there are no loop-carried
# dependencies across j.
j_loop_stage2 = p.find_loop("j #1")  # second 'j' loop is Stage 2
p = parallelize_loop(p, j_loop_stage2)

# Simplify the resulting IR (constant folding, dead code cleanup, etc.).
p = simplify(p)

# Expose the scheduled kernel under the public name expected by the C driver.
kernel_atax = rename(p, "kernel_atax")
/* EXO END */


