from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Baseline ATAX kernel: y = A^T * (A * x)
@proc
def kernel_atax(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Initialize y to zero
    for j in seq(0, n):
        y[j] = 0.0

    # Compute tmp = A * x and y = A^T * tmp
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]
        for j in seq(0, n):
            y[j] += A[i, j] * tmp[i]


# ---------------------------------------------------------------------------
# Scheduling / optimization
# ---------------------------------------------------------------------------

# Tile size for the inner j-dimension. This is a tuning knob that can be
# adjusted for different cache sizes or vector widths.
J_TILE = 64

# Start from a simplified version of the kernel.
kernel_atax = simplify(kernel_atax)

# 1) Fission the loop over i so that tmp and y updates are separated.
#    Original structure inside the i-loop:
#      tmp[i] = 0.0          (stmt 0)
#      for j ... tmp[i]+=    (stmt 1)
#      for j ... y[j] +=     (stmt 2)
#
#    We fission between stmt 1 and stmt 2, lifting the surrounding i-loop
#    once. Result:
#      for i: tmp-computation only
#      for i: y-update only
i_loop = kernel_atax.find_loop("i")
i_body = i_loop.body()
gap_after_tmp_compute = i_body[1].after()
kernel_atax = fission(kernel_atax, gap_after_tmp_compute, n_lifts=1)

# 2) Parallelize the tmp = A * x computation across i. Each iteration of
#    this i-loop writes to a distinct tmp[i] and only reads A and x, so
#    there are no cross-iteration dependences.
i_tmp = kernel_atax.find_loop("i #0")
kernel_atax = parallelize_loop(kernel_atax, i_tmp)

# 3) Tile the j loops in both phases to improve cache locality and give
#    the backend fixed-size inner loops that are easy to vectorize.
#
#    3a) Tile j in the tmp = A * x phase.
i_tmp = kernel_atax.find_loop("i #0")
j_tmp = i_tmp.find_loop("j")
kernel_atax = divide_loop(kernel_atax, j_tmp, J_TILE, ("jo", "ji"), tail="guard")

#    3b) Tile j in the y = A^T * tmp phase.
i_y = kernel_atax.find_loop("i #1")
j_y = i_y.find_loop("j")
kernel_atax = divide_loop(kernel_atax, j_y, J_TILE, ("jo", "ji"), tail="guard")

